##server:rsync
##type:poc
##params:root_url
##name:rsync_Unauthorized_access_poc
##severity:high
##out_put:

loglevel(`info`)
yakit.AutoInitYakit()

target = cli.String("root_url")
ip, port, _ = str.ParseStringToHostPort(target)
// dump(ip,port)
conn,err= tcp.Connect(ip, port)
if err != nil {
    die(err)
}

conn.send("test")
// dump(conn)
result,_ := conn.RecvStringTimeout(10)
addr := str.HostPort(ip, port)
if str.MatchAllOfSubString(result, "@RSYNCD:") {
    risk.NewRisk(
    target, risk.severity("high"), 
    risk.title(f"FOUND ${target} rsync 未授权访问"),
    risk.titleVerbose(" rsync 未授权访问"),
    risk.type("信息窃取"), risk.typeVerbose("权限许可和访问控制"),
    risk.details({
        "request":"test",
        "respone":result,
        "target":target,
    }),
    )
}else{}
